rameClass = `group relative block overflow-hidden rounded-xl bg-black ${compact ? \"aspect-square\" : \"aspect-[4/5] max-h-[430px]\"}`;\n          return (\n            <article\n              key={`${item.imageUrl}-${index}`}\n              className={`shrink-0 snap-start rounded-2xl border border-hairline bg-carbon p-1.5 ${compact ? \"w-[min(70vw,220px)] md:w-[calc((100%_-_3rem)/5)]\" : \"w-[min(82vw,360px)] md:w-[calc((100%_-_1.5rem)/3)]\"}`}\n            >\n              {href ? (\n                <a\n                  href={href}\n                  target={external ? \"_blank\" : undefined}\n                  rel={external ? \"noopener noreferrer\" : undefined}\n                  aria-label={`${item.title || \"\u062f\u06cc\u062f\u0646 \u062a\u0635\u0648\u06cc\u0631\"}${insta ? \" \u062f\u0631 \u0627\u06cc\u0646\u0633\u062a\u0627\u06af\u0631\u0627\u0645\" : \"\"}`}\n                  className={frameClass}\n                >\n                  {frame}\n                </a>\n              ) : (\n                <div className={frameClass}>{frame}</div>\n              )}\n              {!compact && (item.title || item.caption) && (\n                <div className=\"p-3\">\n                  {item.title && <h2 className=\"text-base font-bold text-bone\">{item.title}</h2>}\n                  {item.caption && (\n                    <p className=\"mt-1 text-sm leading-7 text-metal\">{item.caption}</p>\n                  )}\n                </div>\n              )}\n            </article>\n          );\n        })}\n      </div>\n    </div>\n  );\n}\n"}}''')
